<script lang="ts">
 import {onMount} from 'svelte';import {Calendar,Clock,Play,Plus,Square,GitBranch,RotateCw,Users} from '@lucide/svelte';import Guard from '$lib/Guard.svelte';import Notice from '$lib/Notice.svelte';import {session,api,refresh,date} from '$lib/api';import type {AdminView} from '$lib/types';let data=$state<AdminView|null>(null);let error=$state('');let busy=$state(false);let name=$state('Example Branch practice');let template=$state('');let hours=$state(4);let confirmation:HTMLDialogElement;let action=$state('');
 async function load(){try{await refresh();if($session?.user.admin){data=await api<AdminView>('/api/admin');if(!template)template=data.templates.find(t=>t.built)?.id??''}}catch(e){error=(e as Error).message}}
 onMount(()=>{void load();const t=setInterval(load,5000);return()=>clearInterval(t)});
 async function run(path:string,body:unknown={}){busy=true;error='';try{await api(path,body);confirmation?.close();await load()}catch(e){error=(e as Error).message}finally{busy=false}}
 function confirm(which:string){action=which;confirmation.showModal()}
</script>
<svelte:head><title>Manage meeting · LabCentral</title></svelte:head>
<div class="flex flex-wrap items-start justify-between gap-5"><div><h1 class="text-3xl font-semibold tracking-tight sm:text-4xl">Manage meeting</h1><p class="mt-3 text-base-content/70">Prepare the branches. Keep the session moving.</p></div><a href="/admin/templates/" class="btn btn-sm"><GitBranch size={16}/>Templates</a></div>
<Guard admin><Notice message={error}/>{#if data}
{#if !data.meeting||data.meeting.status==='ended'}<form class="mt-10 max-w-xl" onsubmit={(e)=>{e.preventDefault();void run('/api/admin/meeting',{name,template,hours,teamCount:5,capacity:4})}}><fieldset class="fieldset"><legend class="fieldset-legend text-lg">Create a meeting</legend><label class="label" for="meeting-name">Meeting name</label><input class="input w-full" id="meeting-name" bind:value={name} maxlength="100" required/><label class="label mt-3" for="template">Built template revision</label><select id="template" class="select w-full" bind:value={template} required><option value="" disabled>Choose a built revision</option>{#each data.templates.filter(t=>t.built) as t}<option value={t.id}>{t.name} · {t.commit.slice(0,7)}</option>{/each}</select><label class="label mt-3" for="duration">Hours until automatic cleanup</label><input id="duration" class="input w-full" type="number" min="1" max="8" bind:value={hours} required/><p class="mt-2 text-sm text-base-content/70">Five teams, four students per team. Machines and files are deleted at the deadline.</p><button disabled={busy||!template} class="btn btn-primary mt-5"><Plus size={17}/>Create meeting</button></fieldset></form>{#if !data.templates.some(t=>t.built)}<p class="mt-5 text-sm">First, <a class="link" href="/admin/templates/">build a template</a>.</p>{/if}
{:else}<section class="mt-10 border-y border-base-300 py-6"><div class="flex flex-wrap items-start justify-between gap-5"><div><h2 class="flex items-center gap-3 text-2xl font-semibold"><Calendar size={22}/>{data.meeting.name}</h2><p class="mt-3 flex items-center gap-2 text-sm text-base-content/70"><Clock size={16}/>Cleanup at {date(data.meeting.expires)}<span class="badge badge-sm">{data.meeting.status}</span></p></div><div class="flex flex-wrap gap-2">{#if data.meeting.status!=='ending'}<button class="btn btn-sm btn-primary" disabled={busy||data.teams.every(t=>t.status==='ready')} onclick={()=>confirm('prepare')}><Play size={16}/>Prepare labs</button><button class="btn btn-sm" disabled={busy} onclick={()=>run('/api/admin/extend',{hours:1})}><Plus size={16}/>Add one hour</button><button class="btn btn-sm btn-ghost" disabled={busy} onclick={()=>confirm('end')}><Square size={16}/>End meeting</button>{/if}</div></div></section>
 <div class="mt-7 max-w-full overflow-x-auto"><table class="table table-sm"><thead><tr><th>Team</th><th>Members</th><th>Lab</th></tr></thead><tbody>{#each data.teams as team}<tr><th><span class="flex items-center gap-2"><Users size={16}/>{team.name}</span></th><td>{team.members} / {team.capacity}</td><td><span class="badge badge-sm">{team.status}</span></td></tr>{/each}</tbody></table></div>{/if}
 <section class="mt-12"><h2 class="text-xl font-semibold">Operations</h2><ul class="mt-4 divide-y divide-base-300">{#each data.jobs as job}<li class="flex flex-wrap items-start gap-4 py-4"><RotateCw size={17} class="mt-1"/><div class="min-w-0 flex-1"><p class="font-medium capitalize">{job.kind} <span class="badge badge-sm ml-2">{job.status}</span></p>{#if job.error}<p class="mt-2 break-words text-sm text-error">{job.error}</p>{/if}</div>{#if job.status==='failed'}<button class="btn btn-sm" disabled={busy} onclick={()=>run('/api/admin/jobs/retry',{id:job.id})}>Retry recovery</button>{/if}</li>{:else}<li class="py-6 text-sm text-base-content/70">No operations yet. Create a meeting when your images are ready.</li>{/each}</ul></section>
{/if}</Guard>
<dialog bind:this={confirmation} class="modal" aria-labelledby="confirm-title"><div class="modal-box"><h2 id="confirm-title" class="text-xl font-semibold">{action==='end'?'End this meeting?':'Prepare the team labs?'}</h2><p class="mt-4 leading-relaxed">{action==='end'?`This deletes machines and workspace files for ${data?.teams.map(t=>t.name).join(', ')}. This cannot be undone.`:`This starts four machines for each of ${data?.teams.length??0} teams. The five-team compute estimate is $1.14 per hour, plus storage, public addresses, transfer, and any burst credits. Cleanup follows the meeting deadline.`}</p><Notice message={error}/><div class="modal-action"><form method="dialog"><button class="btn btn-sm">Cancel</button></form><button class="btn btn-sm" class:btn-error={action==='end'} class:btn-primary={action==='prepare'} disabled={busy} onclick={()=>run('/api/admin/'+action)}>{action==='end'?'Delete team labs':'Prepare labs'}</button></div></div></dialog>
